"""
Static DAX function reference library — every function in Microsoft's DAX
function reference (as organized in the official docs, current through the
2026 Power BI / Fabric DAX surface), each with what it does, its syntax, and
a short worked example.

Deliberately not fetched from the internet or generated by a model at
runtime: this ships as plain data so the tool works fully offline and the
content is stable and auditable. FUNCTIONS is keyed by the function's
canonical uppercase name; DAX itself is case-insensitive on function names,
so lookups elsewhere in this app normalize to uppercase before indexing in.
"""
from __future__ import annotations

from dataclasses import dataclass


@dataclass
class FunctionInfo:
    name: str
    category: str
    description: str
    syntax: str
    example: str


