FUNCTIONS: dict[str, FunctionInfo] = {}
for _name, _cat, _desc, _syntax, _example in _RAW:
    # A few names legitimately appear in two categories (e.g. VALUES, BLANK,
    # UNICHAR) — keep the first (more specific) entry, don't overwrite it.
    if _name not in FUNCTIONS:
        FUNCTIONS[_name] = FunctionInfo(_name, _cat, _desc, _syntax, _example)


def get_function(name: str) -> FunctionInfo | None:
    return FUNCTIONS.get(name.upper())


def all_functions() -> list[FunctionInfo]:
    return sorted(FUNCTIONS.values(), key=lambda f: (f.category, f.name))
